package main
import("flag";"fmt";"log";"net/http";"os";"strings";"time";"github.com/jimlucas/zbx-ssh-gateway/internal/api";"github.com/jimlucas/zbx-ssh-gateway/internal/config";"github.com/jimlucas/zbx-ssh-gateway/internal/gateway";"github.com/jimlucas/zbx-ssh-gateway/internal/sshclient")
func main(){path:=flag.String("config","/etc/zbx-ssh-gateway/gateway.local.yaml","local configuration file");flag.Parse();c,e:=config.Load(*path);if e!=nil{log.Fatal(e)};token:="";if c.API.BearerTokenFile!=""{b,e:=os.ReadFile(c.API.BearerTokenFile);if e!=nil{log.Fatal(e)};token=strings.TrimSpace(string(b))};sc:=sshclient.Config{Username:c.SSH.Username,Port:c.SSH.Port,Passwords:c.SSH.PasswordList.Passwords,ConnectTimeout:c.SSH.ConnectTimeout,CommandTimeout:c.SSH.CommandTimeout,KnownHosts:c.SSH.KnownHosts,MaxOutputBytes:c.Limits.MaxOutputBytes};ex:=&gateway.SSHExecutor{Ops:c.Operations,Client:sshclient.New(sc)};m:=gateway.New(c.Limits.MaxWorkers,c.Limits.MaxQueue,ex);a:=&api.Server{Manager:m,Token:token,MaxBody:c.Limits.MaxRequestBytes};srv:=&http.Server{Addr:fmt.Sprintf("%s:%d",c.Server.Listen,c.Server.Port),Handler:a.Handler(),ReadHeaderTimeout:5*time.Second,ReadTimeout:15*time.Second,WriteTimeout:30*time.Second,IdleTimeout:60*time.Second};log.Printf("zbx-ssh-gateway listening on %s",srv.Addr);if c.Server.TLS.Enabled{log.Fatal(srv.ListenAndServeTLS(c.Server.TLS.Certificate,c.Server.TLS.PrivateKey))};log.Fatal(srv.ListenAndServe())}
